/*
1 维护机场默认时区
2 运行时，若数据源读入airport存在，则以数据源 airport对象为准
3 运行时，若数据源读入airport不存在，则以下面默认时区（minutes）为准
	PEK,480
	URO,60
	URY,180
	USH,-180
	USK,180
	USL,480
	USM,420
	USN,540
*/
#include "AirportDefaultTmOffset.h"
#include <iostream>
#include <climits>

using namespace std;
static void initDefaultAiportOffsetMinutes();

//singleton
static AirportDefault g_instance;
AirportDefault& AirportDefault::instance() {
	return g_instance;
}

//目标airport是否在 default中
bool AirportDefault::isDefaultExist(string airport) {
	if (_defaultAiportOffsetMinutes.empty()) {
		initDefaultAiportOffsetMinutes();
		initDefaultCountry();
	}
	return _defaultAiportOffsetMinutes.find(airport) != _defaultAiportOffsetMinutes.end();
}

//目标airport不存在，返回 ""
std::string AirportDefault::getCountry(std::string airport) {
	if (_defaultAiportCountry.empty()) {
		initDefaultAiportOffsetMinutes();
		initDefaultCountry();
	}

	if (_defaultAiportCountry.find(airport) == _defaultAiportCountry.end()) {
		return "";
	}
	if (!_warnedAirport[airport]) {
		_warnedAirport[airport] = true;
		cout << "ERROR: airport '" << airport << "' not found, default countr=" << _defaultAiportCountry[airport] << endl;
	}
	return _defaultAiportCountry[airport];
}


//若airport不存在, 返回 INT_MAX
int AirportDefault::getOffsetMinutes(string airport) {

	if (_defaultAiportOffsetMinutes.empty()) {
		initDefaultAiportOffsetMinutes();
		initDefaultCountry();
	}

	if (_defaultAiportOffsetMinutes.find(airport) == _defaultAiportOffsetMinutes.end()) {
		return INT_MAX;
	}
	if (!_warnedAirport[airport]) {
		_warnedAirport[airport] = true;
		cout << "ERROR: airport '" << airport << "' not found, default offset minute =" << _defaultAiportOffsetMinutes[airport] << endl;
	}
	return _defaultAiportOffsetMinutes[airport];
}

//若airport不存在, 返回 INT_MAX
double AirportDefault::getOffsetHour(string airport) {

	if (_defaultAiportOffsetMinutes.empty()) {
		initDefaultAiportOffsetMinutes();
		initDefaultCountry();
	}
	if (_defaultAiportOffsetMinutes.find(airport) == _defaultAiportOffsetMinutes.end()) {
		return INT_MAX;
	}
	if (!_warnedAirport[airport]) {
		_warnedAirport[airport] = true;
		cout << "ERROR: airport '" << airport << "' not found, default offset minutes =" << _defaultAiportOffsetMinutes[airport] << endl;
	}
	return _defaultAiportOffsetMinutes[airport] / 60.0;
}
